class FamilyCarePage extends StatefulWidget { const FamilyCarePage({super.key}); @override State<FamilyCarePage> createState()=>_FamilyCarePageState(); }
class _FamilyCarePageState extends State<FamilyCarePage>{ int selected=0; late final members=<FamilyMember>[const FamilyMember(id:'self',name:'You',relationship:'Primary profile',initials:'ME',access:FamilyMemberAccess.owner,nextCareLabel:'Your care plan',isSelf:true),const FamilyMember(id:'mother',name:'Samira Hassan',relationship:'Mother',initials:'SH',access:FamilyMemberAccess.shared,nextCareLabel:'Blood pressure review'),const FamilyMember(id:'child',name:'Omar Hassan',relationship:'Child',initials:'OH',access:FamilyMemberAccess.pending,nextCareLabel:'Vaccination reminder')]; @override Widget build(BuildContext c){final l=AppLocalizations.of(c);return Scaffold(appBar:AppBar(title:Text(l.familyCareTitle)),body:ListView(padding:const EdgeInsetsDirectional.all(20),children:[Text(l.familyCareSubtitle,style:Theme.of(c).textTheme.bodyLarge),const SizedBox(height:16),...List.generate(members.length,(i){final m=members[i];return Card(child:ListTile(selected:selected==i,onTap:()=>setState(()=>selected=i),leading:CircleAvatar(child:Text(m.initials)),title:Text(m.name),subtitle:Text('${m.relationship} · ${m.nextCareLabel}'),trailing:m.access==FamilyMemberAccess.pending?Chip(label:Text(l.familyCarePending)):const Icon(Icons.chevron_right));}),const SizedBox(height:12),OutlinedButton.icon(onPressed:()=>context.push('/settings/privacy'),icon:const Icon(Icons.shield_outlined),label:Text(l.familyCarePrivacy))]));}}
